def test_split_statements():
    sql = "SELECT * FROM tab1; SELECT * FROM tab2;"
    assert len(split(sql)) == 2

def test_split_statements_with_heading_and_ending_new_line():
    sql = "
SELECT * FROM tab1;
SELECT * FROM tab2;
"
    assert len(split(sql)) == 2

def test_split_statements_with_comment():
    sql = """SELECT 1;

-- SELECT 2;"""
    assert len(split(sql)) == 1

def test_split_statements_with_show_create_table():
    sql = """SELECT 1;

SHOW CREATE TABLE tab1;"""
    assert len(split(sql)) == 2

def test_split_statements_with_desc():
    sql = """SELECT 1;

DESC tab1;"""
    assert len(split(sql)) == 2

def test_split_statement_ends_with_multiple_semicolons():
    sql = "SELECT 1;;;"
    assert len(split(sql)) == 1

def test_runner_dummy():
    runner = LineageRunner(
        """insert into tab2 select col1, col2, col3, col4, col5, col6 from tab1;
insert into tab3 select * from tab2""",
        verbose=True,
    )
    assert str(runner)
    assert runner.to_cytoscape() is not None
    assert runner.to_cytoscape(level=LineageLevel.COLUMN) is not None

def test_get_column_lineage_exclude_subquery_inpath():
    v_sql = "insert into ta select b from (select b from tb union all select c from tc ) sub"
    parse = LineageRunner(sql=v_sql)
    for col_tuple in parse.get_column_lineage(exclude_subquery_columns=True):
        for col in col_tuple:
            assert not isinstance(col.parent, SubQuery)

@patch.dict(
    os.environ,
    {
        "SQLLINEAGE_DIRECTORY": os.path.join(os.path.dirname(__file__), "data"),
        "SQLLINEAGE_DEFAULT_SCHEMA": "<default>",
        "SQLLINEAGE_TSQL_NO_SEMICOLON": "true",
    },
)
def test_config():
    assert type(SQLLineageConfig.DIRECTORY) is str
    assert SQLLineageConfig.DIRECTORY == os.path.join(os.path.dirname(__file__), "data")

    assert type(SQLLineageConfig.DEFAULT_SCHEMA) is str
    assert SQLLineageConfig.DEFAULT_SCHEMA == "<default>"

    assert type(SQLLineageConfig.TSQL_NO_SEMICOLON) is bool
    assert SQLLineageConfig.TSQL_NO_SEMICOLON is True

@pytest.mark.parametrize("pool", ["ThreadPoolExecutor", "ProcessPoolExecutor"])
def test_config_parallel(pool: str):
    executor_class = getattr(concurrent.futures, pool)
    schemas = [f"db{i}" for i in range(100)]
    with executor_class() as executor:
        futures = [executor.submit(_check_schema, schema) for schema in schemas]
        for i, future in enumerate(futures):
            assert future.result() == schemas[i]

def test_file_exception():
    for args in (["-f", str(Path().absolute())], ["-f", "nonexist_file"]):
        with pytest.raises(SystemExit) as e:
            main(args)
        assert e.value.code == 1

@patch("builtins.open", side_effect=PermissionError())
def test_file_permission_error(_):
    with pytest.raises(SystemExit) as e:
        main(["-f", __file__])
    assert e.value.code == 1

def test_sqlalchemy_metadata_provider_query_fail():
    provider = SQLAlchemyMetaDataProvider("sqlite:///:memory:")
    assert (
        provider._get_table_columns("non_existing_schema", "non_existing_table") == []
    )
    assert provider._get_table_columns("main", "non_existing_table") == []

def test_return_none_find_from_expression_element():
    file_segment = Linter(dialect="ansi").parse_string("TRUNCATE TABLE tab").tree
    assert find_from_expression_element(file_segment) is None
